al(v)  // struct to JSON bytes",\n    "json.Unmarshal(data, &v)  // JSON bytes to struct",\n    "json.NewEncoder(w).Encode(v)  // stream encode to writer",\n    "json.NewDecoder(r).Decode(&v)  // stream decode from reader",\n    "encoding/csv.NewReader(r)  // CSV reader",\n    "reader.Read()  // reads one CSV record",\n    "reader.ReadAll()  // reads all CSV records",\n    "encoding/csv.NewWriter(w)  // CSV writer",\n    "writer.Write(record)  // writes one CSV record",\n    "writer.Flush()  // flushes CSV writer",\n    "encoding/xml.Marshal(v)  // struct to XML bytes",\n    "encoding/xml.Unmarshal(data, &v)  // XML to struct",\n    "encoding/base64.StdEncoding.EncodeToString(data)  // base64 encode",\n    "encoding/base64.StdEncoding.DecodeString(s)  // base64 decode"\n   ]\n  },\n  "graphql": {\n   "Schema": [\n    "type Query { hello: String }  // Define Query type with field",\n    "type Mutation { createUser(name: String!): User }  // Define Mutation type",\n    "type User { id: ID! name: String! email: String }  // Non-null fields with !",\n    "[Post!]!  // Non-null list of non-null Posts",\n    "input CreateUserInput { name: String! email: String! }  // Input type for mutations",\n    "enum Role { ADMIN USER GUEST }  // Enum type definition",\n    "type Query { users(limit: Int): [User] }  // Query with optional argument"\n   ],\n   "Queries": [\n    "query { user(id: \\"1\\") { name email } }  // Basic query with argument",\n    "query getUser($id: ID!) { user(id: $id) { name } }  // Query with variable",\n    "fragment userFields on User { name email avatar }  // Reusable fragment",\n    "query { author: user(id: \\"1\\") { name } reviewer: user(id: \\"2\\") { name } }  // Aliases",\n    "query { users { ...userFields } }  // Spread fragment in query",\n    "query ($limit: Int) { users(limit: $limit) { id name } }  // Variable query",\n    "{ posts { title author { name } } }  // Nested relation query"\n   ],\n   "Mutations": [\n    "mutation { createUser(